namespace Fanex.BetList.Core.UnitTest.Builder.ChoiceBuilder
{
    using Fanex.BetList.Core.Builder.ChoiceBuilder;
    using Fanex.BetList.Core.UnitTest.Common.Templates;
    using Fanex.BetList.Core.UnitTest.Common.Enums;
    using NUnit.Framework;
    using System;

    public class Choice28Test
    {
        private ChoiceCreator _choiceCreator;
        private const string BetTeamHandicap = "/div/span[1]/span[2][@class=\"handicap\"]";
        private const string BetTeamTemplate = "{0}&nbsp;<span class=\"underdog\">({1})</span><span class='handicap'> </span>";

        [SetUp]
        public void Setup()
        {
            _choiceCreator = new ChoiceCreator(new Choice28(), BetTypes._3_Way_Handicap);
        }

        [Test]
        public void Ticket_VisibleSpanHandicap()
        {
            // Act
            string actualValue = _choiceCreator.GetFirstChildInnerHtml(BetTeamHandicap);

            // Assert
            string expected = " ";
            Assert.AreEqual(expected, actualValue);
        }

        [Test]
        public void BetTeamOfTicketIs1_ShowSpanBetTeamWithTeamNameIsHomeTeamAndHandicapIsHandicap2SubtractHandicap1()
        {
            // Arrange
            _choiceCreator.Ticket.BetTeam = "1";
            _choiceCreator.Ticket.Handicap1 = 1;
            _choiceCreator.Ticket.Handicap2 = 2;

            // Act
            string actualValue = _choiceCreator.GetInnerHtml(XPathChoice.BetTeam);

            // Assert
            string handicap = "+" + (_choiceCreator.Ticket.Handicap2 - _choiceCreator.Ticket.Handicap1).ToString();
            string expected = string.Format(BetTeamTemplate, _choiceCreator.TicketHelperStub.GetTeamNameById(_choiceCreator.Ticket.HomeId), handicap);
            Assert.AreEqual(expected, actualValue);
        }

        [Test]
        public void BetTeamOfTicketIs2_ShowSpanBetTeamWithTeamNameIsAwayTeamAndHandicapIsHandicap1SubtractHandicap2()
        {
            // Arrange
            _choiceCreator.Ticket.BetTeam = "2";
            _choiceCreator.Ticket.Handicap1 = 2;
            _choiceCreator.Ticket.Handicap2 = 1;

            // Act
            string actualValue = _choiceCreator.GetInnerHtml(XPathChoice.BetTeam);

            // Assert
            string handicap = "+" + (_choiceCreator.Ticket.Handicap1 - _choiceCreator.Ticket.Handicap2).ToString();
            string expected = string.Format(BetTeamTemplate, _choiceCreator.TicketHelperStub.GetTeamNameById(_choiceCreator.Ticket.AwayId), handicap);
            Assert.AreEqual(expected, actualValue);
        }

        [Test]
        public void BetTeamOfTicketIsEmptyAndHandicap1Is2AndHandicap2Is1_ShowSpanBetTeamWithTeamNameIsLableDrawAndHandicapIsLableA()
        {
            // Arrange
            _choiceCreator.Ticket.BetTeam = string.Empty;
            _choiceCreator.Ticket.Handicap1 = 2;
            _choiceCreator.Ticket.Handicap2 = 1;

            // Act
            string actualValue = _choiceCreator.GetInnerHtml(XPathChoice.BetTeam);

            // Assert
            string handicap = "A&nbsp;+" + (_choiceCreator.Ticket.Handicap1 - _choiceCreator.Ticket.Handicap2).ToString();
            string expected = string.Format(BetTeamTemplate, TemplateChoice.Draw, handicap);
            Assert.AreEqual(expected, actualValue);
        }

        [Test]
        public void BetTeamOfTicketIsEmptyAndHandicap1Is1AndHandicap2Is2_ShowSpanBetTeamWithTeamNameIsLableDrawAndHandicapIsLableH()
        {
            // Arrange
            _choiceCreator.Ticket.BetTeam = string.Empty;
            _choiceCreator.Ticket.Handicap1 = 1;
            _choiceCreator.Ticket.Handicap2 = 2;

            // Act
            string actualValue = _choiceCreator.GetInnerHtml(XPathChoice.BetTeam);

            // Assert
            string handicap = "H&nbsp;+" + (Math.Abs(_choiceCreator.Ticket.Handicap1 - _choiceCreator.Ticket.Handicap2)).ToString();
            string expected = string.Format(BetTeamTemplate, TemplateChoice.Draw, handicap);
            Assert.AreEqual(expected, actualValue);
        }

        [Test]
        public void BetTeamOfTicketIsEmptyAndHandicap1Is1AndHandicap2Is1_ShowSpanBetTeamWithTeamNameIsLableDrawAndHandicapIsEmpty()
        {
            // Arrange
            _choiceCreator.Ticket.BetTeam = string.Empty;
            _choiceCreator.Ticket.Handicap1 = 1;
            _choiceCreator.Ticket.Handicap2 = 1;

            // Act
            string actualValue = _choiceCreator.GetInnerHtml(XPathChoice.BetTeam);

            // Assert
            string handicap = (_choiceCreator.Ticket.Handicap1 - _choiceCreator.Ticket.Handicap2).ToString();
            string expected = string.Format(BetTeamTemplate, TemplateChoice.Draw, handicap);
            Assert.AreEqual(expected, actualValue);
        }

        [Test]
        public void Ticket_ShowBetTeamClassNameIsFavorite()
        {
            // Act
            string actualValue = _choiceCreator.GetHtmlClassValue(XPathChoice.BetTeam);

            // Assert
            string expected = TemplateChoice.BLFavorite;
            Assert.AreEqual(expected, actualValue);
        }
    }
